svg.script:
(function(){
  'use strict';
  var offStart=document.getElementById('state-off-start');
  var onState=document.getElementById('state-on');
  var offEnd=document.getElementById('state-off-end');
  var video=document.getElementById('tablet-video');
  var audio=document.getElementById('tablet-audio');
  var timedLoop=true;
  var loopDurationMs=60000;
  var audioShouldLoop=true;
  var timer=null;
  var active=false;

  function show(el){ el.removeAttribute('display'); }
  function hide(el){ el.setAttribute('display','none'); }
  function clearTimer(){ if(timer!==null){ clearTimeout(timer); timer=null; } }

  function toEndOff(){
    if(!active) return;
    active=false;
    clearTimer();
    try{ video.pause(); video.currentTime=0; }catch(e){}
    try{ audio.pause(); audio.currentTime=0; }catch(e){}
    video.loop=false;
    audio.loop=false;
    hide(onState); hide(offStart); show(offEnd);
  }

  function turnOn(){
    if(active) return;
    active=true;
    clearTimer();
    hide(offStart); hide(offEnd); show(onState);
    try{ video.currentTime=0; }catch(e){}
    try{ audio.currentTime=0; }catch(e){}
    video.loop=timedLoop;
    audio.loop=audioShouldLoop;
    var p,ap;
    try{ p=video.play(); }catch(e){ p=null; }
    try{ ap=audio.play(); }catch(e){ ap=null; }
    if(p && typeof p.catch==='function'){
      p.catch(function(){ toEndOff(); });
    }
    if(ap && typeof ap.catch==='function'){
      ap.catch(function(){ toEndOff(); });
    }
    if(timedLoop){ timer=setTimeout(toEndOff, loopDurationMs); }
  }

  video.addEventListener('ended',function(){ if(active && !timedLoop) toEndOff(); });
  video.addEventListener('error',function(){ if(active) toEndOff(); });
  audio.addEventListener('error',function(){ if(active) toEndOff(); });

  function bindSwitch(el){
    el.addEventListener('click',turnOn);
    el.addEventListener('keydown',function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){
        ev.preventDefault(); turnOn();
      }
    });
  }
  bindSwitch(document.querySelector('[data-switch="start"]'));
  bindSwitch(document.querySelector('[data-switch="end"]'));
})();
